    box-sizing: border-box;
    font-family: -apple-system, BlinkMacSystemFont, "Segoe UI", Roboto, sans-serif;
}
body {
    background: var(--bg);
    padding: var(--s-md);
    line-height: 1.6;
    -webkit-font-smoothing: antialiased;
}
.panel {
    background: var(--panel-bg);
    border-radius: var(--radius);
    margin-bottom: var(--s-lg);
    overflow: hidden;
    box-shadow: var(--shadow);
    transition: transform 0.2s ease, box-shadow 0.2s ease;
}
.panel:hover {
    transform: translateY(-2px);
    box-shadow: 0 4px 15px rgba(0,0,0,0.1);
}
.panel-body {
    padding: var(--s-lg);
}
.timeline {
    display: flex;
    flex-direction: column;
    gap: var(--s-md);
}
.timeline-header-wrapper {
    display: flex;
    align-items: center;
    gap: var(--s-md);
}
.timeline-avatar {
    width: 44px;
    height: 44px;
    border-radius: 50%;
    border: 1px solid var(--border);
    object-fit: cover;
    transition: transform 0.2s ease;
    flex-shrink: 0;
}
.timeline-avatar:hover {
    transform: scale(1.05);
}
.timeline-user-group {
    display: flex;
    align-items: center;
    gap: var(--s-md);
    flex: 1;
}
.timeline-user-info {
    display: flex;
    flex-direction: column;
    gap: 2px;
}
.timeline-username {
    font-size: 15px;
    font-weight: 600;
    color: var(--text-primary);
}
.timeline-user-title {
    font-size: 11px;
    color: var(--text-tertiary);
}
.timeline-user-level {
    font-size: 11px;
    color: var(--text-secondary);
    background: var(--bg);
    padding: 2px 8px;
    border-radius: 10px;
    white-space: nowrap;
}
.timeline-header-actions {
    display: flex;
    align-items: center;
}
.comment-vote {
    font-size: 11px;
    color: var(--accent);
    text-decoration: none;
    display: flex;
    align-items: center;
    gap: 3px;
    transition: color 0.2s ease;
}
.comment-vote:hover {
    color: #ff2222;
}
.timeline-meta {
    display: flex;
    justify-content: space-between;
    margin: var(--s-sm) 0 var(--s-md) 0;
    font-size: 11px;
    color: var(--text-tertiary);
    padding-left: calc(44px + var(--s-md));
}
.timeline-badge img {
    width: 16px;
    height: 16px;
    margin-right: 4px;
    vertical-align: middle;
}
.timeline-content {
    font-size: 14px;
    color: var(--text-primary);
    margin-bottom: var(--s-md);
    word-break: break-word;
    padding-left: calc(44px + var(--s-md));
}
.timeline-info {
    display: flex;
    justify-content: space-between;
    font-size: 11px;
    color: var(--text-tertiary);
    padding-left: calc(44px + var(--s-md));
}
.timeline-info-reply {
    color: var(--text-secondary);
    margin-right: var(--s-md);
    cursor: pointer;
}
.timeline-info-other-reply {
    color: var(--accent);
    cursor: pointer;
}
.timeline-ft a {
    color: var(--text-secondary);
    text-decoration: none;
    transition: color 0.2s ease;
}
.timeline-ft a:hover {
    color: var(--accent);
}
.reply-line {
    height: 1px;
    background: var(--border);
    margin: var(--s-lg) 0;
}
.other-timelines {
    margin-top: var(--s-md);
    padding-left: calc(44px + var(--s-md));
}
.reply-item {
    display: flex;
    flex-direction: column;
    gap: var(--s-sm);
    margin-bottom: var(--s-md);
    padding: var(--s-md);
    background: var(--bg);
    border-radius: 8px;
}
.reply-header {
    display: flex;
    align-items: center;
    gap: var(--s-md);
}
.reply-avatar {
    width: 36px;
    height: 36px;
    border-radius: 50%;
    border: 1px solid var(--border);
    object-fit: cover;
    flex-shrink: 0;
}
.reply-user-info {
    display: flex;
    flex-direction: column;
    gap: 1px;
}
.reply-username {
    font-size: 14px;
    font-weight: 600;
    color: var(--text-primary);
}
.reply-user-title {
    font-size: 10px;
    color: var(--text-tertiary);
}
.reply-meta {
    display: flex;
    justify-content: space-between;
    font-size: 10px;
    color: var(--text-tertiary);
    margin: 0 0 var(--s-sm) calc(36px + var(--s-md));
}
.reply-content {
    font-size: 13px;
    color: var(--text-primary);
    margin-bottom: var(--s-sm);
    padding-left: calc(36px + var(--s-md));
}
.disclose {
    background: var(--bg);
    padding: var(--s-md);
    border-radius: 8px;
    margin-bottom: var(--s-md);
    display: flex;
    flex-direction: column;
    gap: var(--s-sm);
    padding-left: calc(44px + var(--s-md));
}
.disclose p {
    font-size: 13px;
    color: var(--text-secondary);
}
.disclose a {
    font-size: 13px;
    color: var(--accent);
    text-decoration: none;
    align-self: flex-start;
}
@media (max-width: 360px) {
    body { padding: var(--s-sm); }
    .timeline-avatar { width: 38px; height: 38px; }
    .reply-avatar { width: 32px; height: 32px; }
    .timeline-content, .reply-content, .disclose, .timeline-meta, .timeline-info, .reply-meta {
        padding-left: calc(38px + var(--s-sm));
    }
    .other-timelines { padding-left: calc(38px + var(--s-sm)); }
    .timeline-content { font-size: 13px; }
    .panel-body { padding: var(--s-md); }
    .timeline-badge img { width: 14px; height: 14px; }
}
@media (prefers-color-scheme: dark) {
    :root {
        --bg: #121212;
        --panel-bg: #1e1e1e;
        --text-primary: #f5f5f5;
        --text-secondary: #bbb;
        --text-tertiary: #888;
        --border: #333;
        --accent: #ff6666;
        --shadow: 0 2px 10px rgba(0,0,0,0.2);
    }
}
